116	// settingsTargetFile determines which settings file to write to based on flags
117	// and which files exist. Unlike determineSettingsTarget, this correctly handles
118	// local-only repos by checking for settings.local.json when settings.json is absent.
119	func settingsTargetFile(ctx context.Context, useLocal, useProject bool) (string, string) {
120		if useLocal {
121			return settings.EntireSettingsLocalFile, configDisplayLocal
122		}
123		if useProject {
124			return settings.EntireSettingsFile, configDisplayProject
125		}
126	
127		// No explicit flag — write to whichever file exists.
128		// Check project file first, then local.
129		projectAbs, err := paths.AbsPath(ctx, settings.EntireSettingsFile)
130		if err == nil {
131			if _, statErr := os.Stat(projectAbs); statErr == nil {
132				return settings.EntireSettingsFile, configDisplayProject
133			}
134		}
135		localAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
136		if err == nil {
137			if _, statErr := os.Stat(localAbs); statErr == nil {
138				return settings.EntireSettingsLocalFile, configDisplayLocal
139			}
140		}
141	
142		// Neither exists — default to project
143		return settings.EntireSettingsFile, configDisplayProject
144	}
