146	// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
147	// Supported providers: "github".
148	func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
149		parts := strings.SplitN(value, ":", 2)
150		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
151			return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
152		}
153	
154		provider = parts[0]
155		repo = parts[1]
156	
157		switch provider {
158		case "github":
159			// valid
160		default:
161			return "", "", fmt.Errorf("unsupported provider %q (supported: github)", provider)
162		}
163	
164		repoParts := strings.SplitN(repo, "/", 2)
165		if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
166			return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
167		}
168	
169		return provider, repo, nil
170	}
