188	// runAddAgents shows which agents are currently enabled and lets the user add more.
189	// Already-installed agents cannot be deselected.
190	func runAddAgents(ctx context.Context, w io.Writer, opts EnableOptions) error {
191		installedNames := GetAgentsWithHooksInstalled(ctx)
192	
193		// Show currently installed agents
194		if len(installedNames) > 0 {
195			displayNames := make([]string, 0, len(installedNames))
196			for _, name := range installedNames {
197				if ag, err := agent.Get(name); err == nil {
198					displayNames = append(displayNames, string(ag.Type()))
199				}

200			}
201			fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(displayNames, ", "))
202		}
203	
204		// Build pre-selection set from installed agents
205		installedSet := make(map[types.AgentName]struct{}, len(installedNames))
206		for _, name := range installedNames {
207			installedSet[name] = struct{}{}
208		}
209	
210		// Check if we can prompt interactively
211		if !canPromptInteractively() {
212			fmt.Fprintln(w, "Cannot show agent selection in non-interactive mode.")
213			fmt.Fprintln(w, "Use: entire configure --agent <name>")
214			return nil
215		}
216	
217		// Discover external agent plugins after the interactivity check to avoid
218		// scanning PATH (with a 10s timeout) in non-interactive contexts.
219		// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
220		// during setup the setting doesn't exist yet.
221		external.DiscoverAndRegisterAlways(ctx)
222	
223		// Build options from registered agents
224		agentNames := agent.List()
225		options := make([]huh.Option[string], 0, len(agentNames))
226		for _, name := range agentNames {
227			ag, err := agent.Get(name)
228			if err != nil {
229				continue
230			}
231			if _, ok := agent.AsHookSupport(ag); !ok {
232				continue
233			}
234			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
235				continue
236			}
237			opt := huh.NewOption(string(ag.Type()), string(name))
238			if _, installed := installedSet[name]; installed {
239				opt = opt.Selected(true)
240			}
241			options = append(options, opt)
242		}
243	
244		if len(options) == 0 {
245			return errors.New("no agents with hook support available")
246		}
247	
248		// Check if all agents are already installed
249		allInstalled := true
250		for _, name := range agentNames {
251			ag, err := agent.Get(name)
252			if err != nil {
253				continue
254			}
255			if _, ok := agent.AsHookSupport(ag); !ok {
256				continue
257			}
258			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
259				continue
260			}
261			if _, installed := installedSet[name]; !installed {
262				allInstalled = false
263				break
264			}
265		}
266		if allInstalled {
267			fmt.Fprintln(w, "All available agents are already enabled.")
268			return nil
269		}
270	
271		var selectedAgentNames []string
272		form := NewAccessibleForm(
273			huh.NewGroup(
274				huh.NewMultiSelect[string]().
275					Title("Enable more agents").
276					Description("Use space to select, enter to confirm.").
277					Options(options...).
278					Validate(func(selected []string) error {
279						if len(selected) == 0 {
280							return errors.New("please select at least one agent")
281						}
282						// Ensure previously installed agents are still selected
283						selectedSet := make(map[string]struct{}, len(selected))
284						for _, s := range selected {
285							selectedSet[s] = struct{}{}
286						}
287						for _, name := range installedNames {
288							if _, ok := selectedSet[string(name)]; !ok {
289								ag, err := agent.Get(name)
290								if err != nil {
291									continue
292								}
293								return fmt.Errorf("cannot remove %s — use `entire configure --remove %s` to remove it", ag.Type(), name)
294							}
295						}
296						return nil
297					}).
298					Value(&selectedAgentNames),
299			),

300		)
301		if err := form.Run(); err != nil {
302			return fmt.Errorf("agent selection cancelled: %w", err)
303		}
304	
305		// Find newly selected agents (not previously installed)
306		var newAgents []agent.Agent
307		for _, name := range selectedAgentNames {
308			if _, wasInstalled := installedSet[types.AgentName(name)]; wasInstalled {
309				continue
310			}
311			ag, err := agent.Get(types.AgentName(name))
312			if err != nil {
313				return fmt.Errorf("failed to get agent %s: %w", name, err)
314			}
315			newAgents = append(newAgents, ag)
316		}
317	
318		if len(newAgents) == 0 {
319			fmt.Fprintln(w, "No new agents selected.")
320			return nil
321		}
322	
323		// Install hooks for newly selected agents only
324		for _, ag := range newAgents {
325			if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
326				return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
327			}
328		}
329	
330		// Auto-enable external_agents setting if any new agent is external.
331		for _, ag := range newAgents {
332			if external.IsExternal(ag) {
333				s, loadErr := LoadEntireSettings(ctx)
334				if loadErr != nil {
335					s = &EntireSettings{}
336				}
337				if !s.ExternalAgents {
338					s.ExternalAgents = true
339					var saveErr error
340					if opts.UseLocalSettings {
341						saveErr = SaveEntireSettingsLocal(ctx, s)
342					} else {
343						saveErr = SaveEntireSettings(ctx, s)
344					}
345					if saveErr != nil {
346						return fmt.Errorf("failed to save external_agents setting: %w", saveErr)
347					}
348				}
349				break
350			}
351		}
352	
353		newTypes := make([]string, 0, len(newAgents))
354		for _, ag := range newAgents {
355			newTypes = append(newTypes, string(ag.Type()))
356		}
357		fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(newTypes, ", "))
358	
359		return nil
360	}
